//go:build firefox

package firefox

import (
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	_ "modernc.org/sqlite"

	"github.com/dennis-dko/go-time-recording/test/harness"
)

// Firefox takes the configured logo as the tab's icon, whatever shape it is in.
//
// This is the assertion the other favicon cases could not make. They ask what the
// document declares, or whether the address answers with an image - and both were
// true through two versions of a bug where the tab stayed empty. What a tab draws
// is not in the document and not in the response; it is what the browser decided,
// and the browser is the only one who knows.
//
// Firefox writes that decision down. Every icon it adopts goes into
// favicons.sqlite in its profile, against the page it belongs to, so the question
// can be asked directly rather than inferred.
//
// Three shapes a logo can arrive in, and all three are raster images because
// that is now all a logo may be: an SVG rendered perfectly in the header and on
// the sign-in screen and was still refused as a tab icon by an engine with its
// own rules about what it will rasterise, silently, with nothing in the response
// saying so.
//
// What is left to differ is size, which is where engines rescale rather than
// refuse - so the sizes are what these cover. The number in the store is what
// Firefox rescaled the image to.
func TestFirefoxAdoptsTheLogoAsTheTabIcon(t *testing.T) {
	for name, logo := range map[string]string{
		"a wide wordmark, 600px across":                     "data:image/png;base64,",
		"a wordmark far larger than any tab, 2000px across": "data:image/png;base64,",
		"a small square mark":                               "data:image/png;base64,",
	} {
		t.Run(name, func(t *testing.T) {
			app := harness.Start(t)
			b := openBrowser(t)

			b.goTo(app.BaseURL())
			signIn(t, b)

			post(t, b, "/api/v1/settings/branding",
				fmt.Sprintf(`{"title":"Zeiterfassung","logo":%q}`, logo), "PUT")

			b.goTo(app.BaseURL())

			icons := declaredIcons(t, b)
			if len(icons) != 1 {
				t.Fatalf("the page declares %d icons (%v)", len(icons), icons)
			}

			// Adopting is not instant: the icon is fetched after the document, and
			// written to the store after that.
			adopted := waitForAdoptedIcon(t, b, icons[0])

			if adopted == "" {
				t.Fatalf("Firefox recorded no icon for this page, so the tab stays "+
					"empty however correct %q is", icons[0])
			}

			t.Logf("Firefox adopted %s", adopted)
		})
	}
}

// waitForAdoptedIcon polls Firefox's own store until it has recorded an icon for
// this page, and returns what it recorded.
func waitForAdoptedIcon(t *testing.T, b *browser, href string) string {
	t.Helper()

	// The address without its origin, which is what the store's rows end with.
	wanted := strings.TrimPrefix(href, "/")

	deadline := time.Now().Add(20 * time.Second)

	for {
		for _, row := range recordedIcons(t, b.profile) {
			if strings.Contains(row, wanted) {
				return row
			}
		}

		if time.Now().After(deadline) {
			return ""
		}

		time.Sleep(500 * time.Millisecond)
	}
}

// recordedIcons reads what this Firefox has decided about icons.
//
// Copied before reading: Firefox holds its store open, and the write-ahead log
// beside it holds anything recent - so the main file alone is a view from some
// minutes ago.
func recordedIcons(t *testing.T, profile string) []string {
	t.Helper()

	source := filepath.Join(profile, "favicons.sqlite")
	if _, err := os.Stat(source); err != nil {
		return nil
	}

	copied := filepath.Join(t.TempDir(), fmt.Sprintf("favicons-%d.sqlite", time.Now().UnixNano()))

	for _, suffix := range []string{"", "-wal", "-shm"} {
		body, err := os.ReadFile(source + suffix)
		if err != nil {
			continue
		}

		if err := os.WriteFile(copied+suffix, body, 0o600); err != nil {
			t.Fatalf("copying Firefox's icon store: %v", err)
		}
	}

	db, err := sql.Open("sqlite", copied)
	if err != nil {
		t.Fatalf("opening Firefox's icon store: %v", err)
	}

	defer func() { _ = db.Close() }()

	rows, err := db.Query(`SELECT icon_url, width, length(data) FROM moz_icons ORDER BY id`)
	if err != nil {
		// The store exists but has no table yet, which is simply "nothing decided".
		return nil
	}

	defer func() { _ = rows.Close() }()

	var out []string

	for rows.Next() {
		var (
			url    string
			width  int
			length int
		)

		if err := rows.Scan(&url, &width, &length); err != nil {
			t.Fatalf("reading Firefox's icon store: %v", err)
		}

		// An icon with no bytes is one Firefox looked at and did not keep.
		if length == 0 {
			continue
		}

		out = append(out, fmt.Sprintf("%s (width %d, %d bytes)", url, width, length))
	}

	return out
}
